<?php
declare(strict_types=1);require_once dirname(__DIR__).'/src/helpers.php';$user=require_login();if($user['role']!=='employee'){http_response_code(403);exit('Only employees can edit their orders.');}$id=(int)($_GET['id']??$_POST['id']??0);$q=db()->prepare('SELECT * FROM orders WHERE id=? AND mr_id=?');$q->execute([$id,$user['id']]);$order=$q->fetch();if(!$order){http_response_code(404);exit('Order not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$product=trim($_POST['product']??'');$qty=filter_var($_POST['quantity']??null,FILTER_VALIDATE_INT);$free=filter_var($_POST['free_quantity']??0,FILTER_VALIDATE_INT);$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);$date=$_POST['order_date']??'';if($product===''||$qty===false||$qty<1||$free===false||$free<0||$amount===false||$amount<0){$error='Enter valid order details.';}else{db()->prepare('UPDATE orders SET order_date=?,product=?,quantity=?,free_quantity=?,amount=? WHERE id=? AND mr_id=?')->execute([$date,$product,$qty,$free,$amount,$id,$user['id']]);redirect('party.php?id='.$order['party_id']);}}
page_start('Edit order',$user,'parties');?><form method="post" class="card"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><?php if($error):?><p class="error"><?=e($error)?></p><?php endif;?><label>Date<input type="date" name="order_date" value="<?=e($order['order_date'])?>" required></label><label>Product<input name="product" value="<?=e($order['product'])?>" required></label><label>Quantity<input name="quantity" type="number" min="1" value="<?=e((string)$order['quantity'])?>" required></label><label>Free quantity<input name="free_quantity" type="number" min="0" value="<?=e((string)($order['free_quantity']??0))?>" required></label><label>Final amount<input name="amount" type="number" min="0" step="0.01" value="<?=e((string)$order['amount'])?>" required></label><button>Save correction</button></form><?php page_end($user,'parties');?>
